import { describe, expect, it, vi } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve as resolvePath } from 'node:path'
import { ApiClient, ApiError } from '@/api/client'
import { normaliseAnalysisResult } from '@/api/normalize'

/**
 * The OpenAPI document is generated by the backend and committed to the repo;
 * the client is checked against it so the two cannot drift silently.
 */
const OPENAPI = JSON.parse(
  readFileSync(resolvePath(process.cwd(), '../../packages/contracts/openapi.json'), 'utf8'),
) as { paths: Record<string, Record<string, unknown>> }

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } })
}

function clientWith(fetchImpl: typeof fetch) {
  return new ApiClient({ baseUrl: '', fetchImpl, timeoutMs: 50 })
}

const minimalResult = {
  scenario_id: 'scn',
  scenario_hash: 'sha256:aa',
  phase_id: 'phase-1',
  profile_id: 'DEMO_PROFILE_MANUAL_WHEELCHAIR',
  rulepack_id: 'DEMO_RULEPACK_NOT_LEGAL',
  rulepack_version: '1.0.0',
  rulepack_hash: 'sha256:bb',
  base_graph_version_id: 'demo-graph-v1',
  base_graph_hash: 'sha256:cc',
  phase_graph_id: 'demo-graph-v1~phase-1',
  phase_graph_hash: 'sha256:dd',
  edge_evaluations: [],
  verdicts: [],
  od_results: [],
  counts: {},
}

describe('API contract parity with the generated OpenAPI document', () => {
  const client = new ApiClient({ baseUrl: '' })
  const paths = OPENAPI.paths

  it('declares every route the client calls', () => {
    const routes = [
      '/api/v1/health',
      '/api/v1/projects',
      '/api/v1/projects/{project_id}/graph',
      '/api/v1/projects/{project_id}/scenarios',
      '/api/v1/scenarios/{scenario_id}',
      '/api/v1/scenarios/{scenario_id}/evaluate',
      '/api/v1/runs/{run_id}',
      '/api/v1/runs/{run_id}/manifest',
      '/api/v1/rulesets',
    ]
    for (const route of routes) {
      expect(paths, `missing route ${route}`).toHaveProperty(route)
    }
    // Referenced so the client instance is not optimised away by readers.
    expect(client.baseUrl).toBeTypeOf('string')
  })

  it('uses only HTTP methods the backend actually serves', () => {
    const expectations: [string, string][] = [
      ['/api/v1/projects', 'post'],
      ['/api/v1/projects/{project_id}/scenarios', 'post'],
      ['/api/v1/scenarios/{scenario_id}', 'patch'],
      ['/api/v1/scenarios/{scenario_id}/evaluate', 'post'],
    ]
    for (const [route, method] of expectations) {
      expect(paths[route]).toHaveProperty(method)
    }
  })
})

describe('ApiClient success paths', () => {
  it('returns the evaluation payload with a normalised result', async () => {
    const spy = vi.fn(async () =>
      jsonResponse({
        run: { id: 'run-1', scenario_id: 'scn', scenario_revision: 1, phase_id: 'phase-1', profile_id: 'p', engine_version: 'e', evaluation_instant: 'i', input_hash: 'sha256:1', semantic_hash: 'sha256:2', created_at: 'now' },
        result: minimalResult,
      }),
    )
    const fetchImpl = spy as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    const response = await client.evaluate('scn-1', { profile_id: 'p', phase_id: 'phase-1' })

    expect(response.run.id).toBe('run-1')
    expect(response.result.od_results).toEqual([])
    expect(response.result.warnings).toEqual([])
    const [url, init] = spy.mock.calls[0] as unknown as [string, RequestInit]
    expect(url).toBe('/api/v1/scenarios/scn-1/evaluate')
    expect(init.method).toBe('POST')
    expect(JSON.parse(init.body as string)).toMatchObject({ profile_id: 'p', phase_id: 'phase-1' })
  })

  it('sends the optimistic revision with a scenario patch', async () => {
    const spy = vi.fn(async () => jsonResponse({ id: 'scn-1', revision: 2, edits: [], phases: [] }))
    const fetchImpl = spy as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    await client.patchScenario('scn-1', { expected_revision: 1, edits: [{ op: 'close_edge', target_id: 'E1', params: {} }] })

    const [, init] = spy.mock.calls[0] as unknown as [string, RequestInit]
    expect(init.method).toBe('PATCH')
    expect(JSON.parse(init.body as string).expected_revision).toBe(1)
  })

  it('percent-encodes identifiers', async () => {
    const spy = vi.fn(async () => jsonResponse({ nodes: [], edges: [], evidence: [] }))
    const fetchImpl = spy as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    await client.getGraph('proj/../etc')
    const [url] = spy.mock.calls[0] as unknown as [string]
    expect(url).toBe('/api/v1/projects/proj%2F..%2Fetc/graph')
  })
})

describe('ApiClient error handling', () => {
  const cases: { name: string; status: number; code: string; expected: keyof ApiError }[] = [
    { name: '404 not found', status: 404, code: 'NOT_FOUND', expected: 'isNotFound' },
    { name: '409 revision conflict', status: 409, code: 'REVISION_CONFLICT', expected: 'isRevisionConflict' },
    { name: '422 validation', status: 422, code: 'REQUEST_VALIDATION_ERROR', expected: 'isValidation' },
    { name: '400 bad request', status: 400, code: 'HTTP_400', expected: 'isValidation' },
    { name: '500 server error', status: 500, code: 'HTTP_500', expected: 'status' },
  ]

  it.each(cases)('surfaces $name with the backend envelope intact', async ({ status, code, expected }) => {
    const fetchImpl = vi.fn(async () =>
      jsonResponse({ code, message: 'boom', details: { hint: 'x' }, request_id: 'req-1' }, status),
    ) as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    const error = await client.health().catch((e: unknown) => e)
    expect(error).toBeInstanceOf(ApiError)
    const apiError = error as ApiError
    expect(apiError.status).toBe(status)
    expect(apiError.code).toBe(code)
    expect(apiError.details).toEqual({ hint: 'x' })
    expect(apiError.requestId).toBe('req-1')
    expect(String(apiError[expected])).toBe(expected === 'status' ? String(status) : 'true')
  })

  it('produces a helpful message for a revision conflict', async () => {
    const fetchImpl = vi.fn(async () =>
      jsonResponse(
        {
          code: 'REVISION_CONFLICT',
          message: 'scenario is at revision 4',
          details: { expected_revision: 2, actual_revision: 4 },
          request_id: 'req',
        },
        409,
      ),
    ) as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    const error = (await client
      .patchScenario('scn', { expected_revision: 2, edits: [] })
      .catch((e: unknown) => e)) as ApiError
    expect(error.userMessage).toMatch(/changed since you loaded it/i)
    expect(error.details.actual_revision).toBe(4)
  })

  it('reports an unreachable backend rather than hanging', async () => {
    const fetchImpl = vi.fn(async () => {
      throw new TypeError('Failed to fetch')
    }) as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    const error = (await client.health().catch((e: unknown) => e)) as ApiError
    expect(error.code).toBe('NETWORK_UNREACHABLE')
    expect(error.userMessage).toMatch(/cannot reach the analysis service/i)
  })

  it('times out instead of waiting forever', async () => {
    const fetchImpl = vi.fn(
      (_url: string, init?: RequestInit) =>
        new Promise((_resolve, reject) => {
          init?.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')))
        }),
    ) as unknown as typeof fetch

    const client = new ApiClient({ baseUrl: '', fetchImpl, timeoutMs: 20 })
    const error = (await client.health().catch((e: unknown) => e)) as ApiError
    expect(['REQUEST_TIMEOUT', 'REQUEST_ABORTED', 'NETWORK_UNREACHABLE']).toContain(error.code)
  })

  it('honours an external abort signal', async () => {
    const controller = new AbortController()
    const fetchImpl = vi.fn(
      (_url: string, init?: RequestInit) =>
        new Promise((_resolve, reject) => {
          init?.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')))
        }),
    ) as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    const promise = client.health(controller.signal).catch((e: unknown) => e)
    controller.abort()
    const error = (await promise) as ApiError
    expect(error.code).toBe('REQUEST_ABORTED')
  })

  it('rejects an empty body instead of returning undefined', async () => {
    const fetchImpl = vi.fn(async () => new Response('', { status: 200 })) as unknown as typeof fetch
    const client = clientWith(fetchImpl)
    const error = (await client.health().catch((e: unknown) => e)) as ApiError
    expect(error.code).toBe('EMPTY_RESPONSE')
  })

  it('rejects a malformed analysis payload with a clear code', async () => {
    const fetchImpl = vi.fn(async () =>
      jsonResponse({
        run: { id: 'run-x', scenario_id: 's', scenario_revision: 1, phase_id: 'p', profile_id: 'p', engine_version: 'e', evaluation_instant: 'i', input_hash: 'h', semantic_hash: 's', created_at: 'n' },
        result: { nothing: 'useful' },
      }),
    ) as unknown as typeof fetch

    const client = clientWith(fetchImpl)
    const error = (await client
      .evaluate('scn', { profile_id: 'p', phase_id: 'phase-1' })
      .catch((e: unknown) => e)) as ApiError
    expect(error.code).toBe('MALFORMED_RESPONSE')
  })
})

describe('normaliseAnalysisResult', () => {
  it('fills defaulted arrays so components never read undefined.length', () => {
    const result = normaliseAnalysisResult({ ...minimalResult })
    expect(result.od_results).toEqual([])
    expect(result.verdicts).toEqual([])
    expect(result.edge_evaluations).toEqual([])
    expect(result.warnings).toEqual([])
  })

  it('converts a missing distance into null, never zero', () => {
    const result = normaliseAnalysisResult({
      ...minimalResult,
      od_results: [{ origin_id: 'a', destination_id: 'b', confirmed_reachable: false, possibly_reachable: false }],
    })
    expect(result.od_results[0]?.confirmed_distance_m).toBeNull()
    expect(result.od_results[0]?.possible_distance_m).toBeNull()
  })

  it('rejects a payload that is not an analysis result', () => {
    expect(() => normaliseAnalysisResult(null)).toThrow()
    expect(() => normaliseAnalysisResult({ phase_id: 'p' })).toThrow(/scenario_id/)
  })

  it('keeps numeric distances that are genuinely present', () => {
    const result = normaliseAnalysisResult({
      ...minimalResult,
      od_results: [{ origin_id: 'a', destination_id: 'b', confirmed_reachable: true, confirmed_distance_m: 58 }],
    })
    expect(result.od_results[0]?.confirmed_distance_m).toBe(58)
  })
})